import{_ as o,a0 as l,w as i,s,ao as u,I as t,x as e,a1 as a,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"使用n2n配置二层点对点VPN | LCTT x X-CMD","titleTemplate":false,"description":"使用n2n配置二层点对点VPN | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用n2n配置二层点对点VPN | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用n2n配置二层点对点VPN | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141021 Configuring layer-two peer-to-peer VPN using n2n","title":"使用n2n配置二层点对点VPN","tag":"201412","desc":""},"relativePath":"201412/20141021 Configuring layer-two peer-to-peer VPN using n2n.md","filePath":"[post].md"}'),d={name:"201412/20141021 Configuring layer-two peer-to-peer VPN using n2n.md"};function g(P,n,m,f,b,h){const r=l("Link");return i(),s("div",null,[n[16]||(n[16]=u(`<h1 id="使用n2n配置二层点对点vpn" tabindex="-1">使用n2n配置二层点对点VPN <a class="header-anchor" href="#使用n2n配置二层点对点vpn" aria-label="Permalink to “使用n2n配置二层点对点VPN”">​</a></h1><p>n2n是一个二层点对点虚拟专用网（VPN），它允许用户在网络层面而非应用层面开发典型的P2P应用功能。这就意味着，用户可以获得本地IP可见性（如，属于同一个n2n网络的两台PC可以互相ping通），以及不管他们现在身处哪个网络，只要有相同的网络IP地址就可以访问到。简言之，就像OpenVPN将SSL从应用（如，用于部署https协议）搬到了网络协议一样，n2n将P2P从应用搬到了网络层面。</p><h3 id="n2n主要功能" tabindex="-1">n2n主要功能 <a class="header-anchor" href="#n2n主要功能" aria-label="Permalink to “n2n主要功能”">​</a></h3><p>n2n是一个基于P2P协议的加密的二层专用网。</p><p>加密使用开放协议部署在边缘节点，它使用用户定义的加密钥匙：你自己控制安全，而不用授权给公司，而Skype或Hamachi却是要的。</p><p>各个n2n用户可以同时属于多个网络（或者社区）。</p><p>它拥有在反向通信方向（如，从外部到内部）穿越NAT和防火墙的能力，因此可以到达n2n节点，即使运行在一个专用网中。防火墙不再是IP层面掌控通信的障碍。</p><p>n2n网络并不意味着它是独立的，它可以在n2n和非n2n网络间路由通信。</p><h3 id="n2n架构基于两个组件" tabindex="-1">n2n架构基于两个组件 <a class="header-anchor" href="#n2n架构基于两个组件" aria-label="Permalink to “n2n架构基于两个组件”">​</a></h3><p><strong>超级节点</strong>：它在启动时用于边缘节点或用于达到对称防火墙后面的节点。对于这些节点，该应用主要是一个目录暂存器和包路由器，而不是直接通信。</p><p><strong>边缘节点</strong>：安装在用户PC的应用程序，它允许构建n2n网络。实际上，各个边缘节点创建一个tun/tap设备，该设备是n2n网络的进入点。</p><h3 id="安装n2n到ubuntu" tabindex="-1">安装n2n到Ubuntu <a class="header-anchor" href="#安装n2n到ubuntu" aria-label="Permalink to “安装n2n到Ubuntu”">​</a></h3><p>打开终端并运行以下命令</p><pre><code>$ sudo apt-get install subversion build-essential libssl-dev
$ svn co https://svn.ntop.org/svn/ntop/trunk/n2n
$ cd n2n/n2n_v2
$ make
$ sudo make install
</code></pre><h3 id="使用n2n配置p2p-vpn" tabindex="-1">使用n2n配置P2P VPN <a class="header-anchor" href="#使用n2n配置p2p-vpn" aria-label="Permalink to “使用n2n配置P2P VPN”">​</a></h3><p>首先，我们需要配置一个超级节点和任意数量的边缘节点。</p><p>决定将超级节点放在哪个地方。假设你将它放到了主机a.b.c.d的xyw端口上。</p><p>决定使用何种密码加密来保证数据安全。假设你使用密码encryptme。</p><p>决定你想要使用的网络名称。假设你将它命名为mynetwork。注意，你可以使用超级节点/边缘节点来处理多个网络，不仅仅只有一个哦。</p><p>决定在边缘节点上使用什么IP地址。假设你使用10.1.2.0/24。</p><p>启动应用：</p><h3 id="配置超级节点" tabindex="-1">配置超级节点 <a class="header-anchor" href="#配置超级节点" aria-label="Permalink to “配置超级节点”">​</a></h3><pre><code>supernode -l xyw
</code></pre><h3 id="配置边缘节点" tabindex="-1">配置边缘节点 <a class="header-anchor" href="#配置边缘节点" aria-label="Permalink to “配置边缘节点”">​</a></h3><p>在各个边缘节点，使用以下命令来连接到P2P VPN。</p><pre><code>sudo edge -a 10.1.2.1 -c mynetwork -k encryptme -l a.b.c.d:xyw

sudo edge -a 10.1.2.2 -c mynetwork -k encryptme -l a.b.c.d:xyw
</code></pre><h3 id="现在来测试你的n2n网络" tabindex="-1">现在来测试你的n2n网络 <a class="header-anchor" href="#现在来测试你的n2n网络" aria-label="Permalink to “现在来测试你的n2n网络”">​</a></h3><pre><code>edge node1&gt; ping 10.1.2.2

edge node2&gt; ping 10.1.2.1
</code></pre><p>Windows n2n VPN客户端（N2N边缘图形界面）</p>`,29)),t("p",null,[n[1]||(n[1]=e("你可以从",-1)),a(r,{href:"http://sourceforge.net/projects/n2nedgegui/"},{default:p(()=>[...n[0]||(n[0]=[e("这里",-1)])]),_:1}),n[2]||(n[2]=e("下载N2N边缘图形界面。",-1))]),n[17]||(n[17]=t("p",null,"N2N边缘图形界面是一个基本的安装器和用于点对点‘n2n VPN解决方案’的GUI配置界面。",-1)),n[18]||(n[18]=t("p",null,[t("img",{src:"http://www.ubuntugeek.com/wp-content/uploads/2014/10/client.jpg",alt:""})],-1)),n[19]||(n[19]=t("hr",null,null,-1)),t("p",null,[n[4]||(n[4]=e("via: ",-1)),a(r,{href:"http://www.ubuntugeek.com/configuring-layer-two-peer-to-peer-vpn-using-n2n.html"},{default:p(()=>[...n[3]||(n[3]=[e("http://www.ubuntugeek.com/configuring-layer-two-peer-to-peer-vpn-using-n2n.html",-1)])]),_:1})]),t("p",null,[n[8]||(n[8]=e("作者：",-1)),a(r,{href:"http://www.ubuntugeek.com/author/ubuntufix"},{default:p(()=>[...n[5]||(n[5]=[e("ruchi",-1)])]),_:1}),n[9]||(n[9]=e(" 译者：",-1)),a(r,{href:"https://github.com/GOLinux"},{default:p(()=>[...n[6]||(n[6]=[e("GOLinux",-1)])]),_:1}),n[10]||(n[10]=e(" 校对：",-1)),a(r,{href:"https://github.com/wxy"},{default:p(()=>[...n[7]||(n[7]=[e("wxy",-1)])]),_:1})]),t("p",null,[n[13]||(n[13]=e("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...n[11]||(n[11]=[e("LCTT",-1)])]),_:1}),n[14]||(n[14]=e(" 原创翻译，",-1)),a(r,{href:"http://linux.cn/"},{default:p(()=>[...n[12]||(n[12]=[e("Linux中国",-1)])]),_:1}),n[15]||(n[15]=e(" 荣誉推出",-1))])])}const T=o(d,[["render",g]]);export{x as __pageData,T as default};
